CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE FUNCTION public.actor_has_platform_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') $$;
CREATE FUNCTION public.is_admin_or_uno_team() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team') $$;
CREATE POLICY own_roles ON user_roles FOR SELECT USING(user_id=auth.uid());
CREATE POLICY own_members ON management_company_members FOR SELECT USING(user_id=auth.uid());
CREATE POLICY own_org ON org_members FOR SELECT USING(user_id=auth.uid());
CREATE POLICY "Anyone can view active providers" ON public.providers FOR SELECT USING (is_active=true);
CREATE POLICY "Owners can manage their own provider" ON public.providers FOR ALL USING (user_id=auth.uid());
CREATE POLICY "Admins can manage all providers" ON public.providers FOR ALL USING (has_role(auth.uid(),'admin'));
CREATE POLICY "Anyone can view approved services or own content" ON public.services FOR SELECT USING ((is_active=true AND approval_status='approved') OR EXISTS(SELECT 1 FROM public.providers p WHERE p.id=provider_id AND p.user_id=auth.uid()));
CREATE POLICY "Providers can manage their own services" ON public.services FOR ALL USING (EXISTS(SELECT 1 FROM public.providers p WHERE p.id=provider_id AND p.user_id=auth.uid()));
CREATE POLICY "Admins can manage all services" ON public.services FOR ALL USING (has_role(auth.uid(),'admin'));
CREATE POLICY "Salons are viewable by everyone" ON public.salons FOR SELECT USING (true);
CREATE POLICY "Anyone can view approved salons or own content" ON public.salons FOR SELECT USING ((is_active=true AND approval_status='approved') OR EXISTS(SELECT 1 FROM public.providers p WHERE p.id=provider_id AND p.user_id=auth.uid()));
CREATE POLICY "Providers can manage own salons" ON public.salons FOR ALL USING (auth.uid()=provider_id);
CREATE POLICY "Admins can view all salons" ON public.salons FOR SELECT USING ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team')));
CREATE POLICY "Admins can update salons" ON public.salons FOR UPDATE USING ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team'))) WITH CHECK ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team')));
CREATE POLICY "Admins can view all cleaning_services" ON public.cleaning_services FOR SELECT USING ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team')));
CREATE POLICY "Admins can update cleaning_services" ON public.cleaning_services FOR UPDATE USING ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team'))) WITH CHECK ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team')));
CREATE POLICY "approved owner read" ON public.cleaning_services FOR SELECT USING ((is_active=true AND approval_status='approved') OR EXISTS(SELECT 1 FROM public.providers p WHERE p.id=provider_id AND p.user_id=auth.uid()));
CREATE POLICY "Admins can view all education_providers" ON public.education_providers FOR SELECT USING ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team')));
CREATE POLICY "Admins can update education_providers" ON public.education_providers FOR UPDATE USING ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team'))) WITH CHECK ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team')));
CREATE POLICY "approved owner read" ON public.education_providers FOR SELECT USING ((is_active=true AND approval_status='approved') OR EXISTS(SELECT 1 FROM public.providers p WHERE p.id=provider_id AND p.user_id=auth.uid()));
CREATE POLICY "Admins can view all events" ON public.events FOR SELECT USING ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team')));
CREATE POLICY "Admins can update events" ON public.events FOR UPDATE USING ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team'))) WITH CHECK ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team')));
CREATE POLICY "approved owner read" ON public.events FOR SELECT USING ((is_active=true AND approval_status='approved') OR EXISTS(SELECT 1 FROM public.providers p WHERE p.id=provider_id AND p.user_id=auth.uid()));
CREATE POLICY "Admins can view all gyms" ON public.gyms FOR SELECT USING ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team')));
CREATE POLICY "Admins can update gyms" ON public.gyms FOR UPDATE USING ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team'))) WITH CHECK ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team')));
CREATE POLICY "approved owner read" ON public.gyms FOR SELECT USING ((is_active=true AND approval_status='approved') OR EXISTS(SELECT 1 FROM public.providers p WHERE p.id=provider_id AND p.user_id=auth.uid()));
CREATE POLICY "Admins can view all water_activities" ON public.water_activities FOR SELECT USING ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team')));
CREATE POLICY "Admins can update water_activities" ON public.water_activities FOR UPDATE USING ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team'))) WITH CHECK ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team')));
CREATE POLICY "approved owner read" ON public.water_activities FOR SELECT USING ((is_active=true AND approval_status='approved') OR EXISTS(SELECT 1 FROM public.providers p WHERE p.id=provider_id AND p.user_id=auth.uid()));
CREATE POLICY "listings_admin_full" ON public.listings FOR ALL USING ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team'))) WITH CHECK ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team')));
CREATE POLICY "listings_public_read" ON public.listings FOR SELECT USING (is_active=true AND (approval_status='approved' OR approval_status IS NULL));
CREATE POLICY "listings_provider_select" ON public.listings FOR SELECT USING (EXISTS(SELECT 1 FROM public.providers p WHERE p.id=provider_id AND p.user_id=auth.uid()));
CREATE POLICY "Admins manage all complexes" ON public.property_complexes FOR ALL USING (is_admin_or_uno_team()) WITH CHECK (is_admin_or_uno_team());
CREATE POLICY "Admins can manage all storefronts" ON public.company_storefronts FOR ALL USING (is_admin_or_uno_team()) WITH CHECK (is_admin_or_uno_team());
CREATE POLICY "Owner can manage complexes" ON public.property_complexes FOR ALL USING (owner_id=auth.uid());
CREATE POLICY "Public can view active complexes" ON public.property_complexes FOR SELECT USING (is_active=true);
CREATE POLICY "Admins can update vendor_locations" ON public.vendor_locations FOR UPDATE USING ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team'))) WITH CHECK ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team')));
CREATE POLICY "Admins have full access to vendor locations" ON public.vendor_locations FOR ALL USING ((has_role(auth.uid(),'admin') OR has_role(auth.uid(),'uno_team')));
CREATE POLICY "Public can view approved locations" ON public.vendor_locations FOR SELECT USING (is_active=true AND approval_status='approved');
CREATE POLICY "Vendors can view own locations" ON public.vendor_locations FOR SELECT USING (org_id IN(SELECT org_id FROM org_members WHERE user_id=auth.uid() AND is_active=true));
CREATE POLICY "thai_businesses_select" ON public.thai_businesses FOR SELECT USING (is_active=true OR owner_id=auth.uid() OR is_admin_or_uno_team());
CREATE POLICY "thai_businesses_update" ON public.thai_businesses FOR UPDATE USING (owner_id=auth.uid() OR is_admin_or_uno_team()) WITH CHECK (owner_id=auth.uid() OR is_admin_or_uno_team());
CREATE POLICY "thai_businesses_delete" ON public.thai_businesses FOR DELETE USING (owner_id=auth.uid() OR is_admin_or_uno_team());
CREATE POLICY "thai_services_select" ON public.thai_business_services FOR SELECT USING (EXISTS(SELECT 1 FROM thai_businesses b WHERE b.id=business_id AND (b.is_active=true OR b.owner_id=auth.uid())) OR is_admin_or_uno_team());
CREATE POLICY "thai_services_write" ON public.thai_business_services FOR ALL USING (EXISTS(SELECT 1 FROM thai_businesses b WHERE b.id=business_id AND b.owner_id=auth.uid()) OR is_admin_or_uno_team()) WITH CHECK (EXISTS(SELECT 1 FROM thai_businesses b WHERE b.id=business_id AND b.owner_id=auth.uid()) OR is_admin_or_uno_team());

CREATE TABLE public.categories(id uuid,name_en text,name_ru text,slug text);
GRANT SELECT ON public.categories TO anon,authenticated,service_role;
